
const steps=[{"title": "Existing feature APIs", "status": "Observed baseline on pinned main", "problem": "Bound scan cost using the requested interval, but apply that interval independently to each copied source timestamp.", "why": "Feature APIs build their own source predicates and aggregate at different grains.", "change": "Every inspected source read receives exact bounds. Some feature joins require timestamp equality or anchor on an aggregate bucket.", "remaining": "Copied timestamps, source coverage and aggregation can disagree even when the SQL bounds match.", "code": "for each physical feature source:\n    WHERE copied_conversation_start >= S\n      AND copied_conversation_start \u003c E\naggregate using that feature's existing joins/buckets", "diff": "Baseline: independently bounded feature-source scans."}, {"title": "New API in PR #33993", "status": "Observed implementation at 0d1b75da68", "problem": "Count distinct eligible conversation/agent pairs with any qualifying assistance use.", "why": "Legacy totals count events, actions or sessions and do not provide one shared adoption population.", "change": "Resolve the filtered population; scan selected-agent feature history; reduce and intersect pairs; use population time for buckets.", "remaining": "Historical work is unbounded. Summary internal timestamp equality, Events copy dependencies and population limitations remain.", "code": "population = existingConversationEligibility(S, E, filters)\nfor feature in sevenFamilies:\n    pairs = DISTINCT featureRows(agent IN population.agents)\n    used += pairs JOIN population ON (conversation_id, agent_user_id)\naggregate(used, bucketTime=population.conversation_time)", "diff": "- exact source bounds in feature predicates\n+ eligible-agent source filter\n+ shared pair intersection after source reduction\n+ population time for adoption buckets"}, {"title": "Align scans with existing APIs", "status": "User-directed baseline; implementation pending", "problem": "Bound source history consistently with the other assistance APIs for the same requested time range.", "why": "Existing feature APIs apply [S,E) to their source clocks; the seven new evidence families currently omit those bounds.", "change": "Pass the requested start and end to every participating physical evidence source and retain exact population eligibility plus the final conversation/agent intersection.", "remaining": "Copied-time disagreement, Summary linkage, cluster-copy coverage and bucket attribution remain separate correctness questions. Production performance remains unmeasured.", "code": "eligibility = existingPopulation(S, E, filters)\nfor physicalSource in featureSources:\n    rows = read(source, startInclusive=S, endExclusive=E,\n                agents=eligibility.agents)\nused = featurePredicate(rows) JOIN eligibility ON pair\n# Match existing API source bounds; review timestamp-copy issues separately.", "diff": "+ requested [S,E) bounds on every participating evidence source\n= exact population eligibility and final pair intersection\n? timestamp-copy, source-coverage and join corrections tracked separately"}];
