let currentStep=0,showChanges=false;
function renderStep(){const step=steps[currentStep];document.getElementById('step-status').textContent=step.status;document.getElementById('step-title').textContent=step.title;const panel=document.getElementById('step-explanation');panel.replaceChildren();for(const [label,key] of [['Problem this step addresses','problem'],['Why the problem exists','why'],['What this step changes','change'],['What remains unresolved','remaining']]){const paragraph=document.createElement('p');const bold=document.createElement('b');bold.textContent=label+': ';paragraph.append(bold,document.createTextNode(step[key]));panel.append(paragraph);}document.getElementById('step-code').textContent=showChanges?step.diff:step.code;document.getElementById('previous').disabled=currentStep===0;document.getElementById('next').disabled=currentStep===steps.length-1;document.getElementById('step-count').textContent=`Step ${currentStep+1} of ${steps.length}`;document.getElementById('snapshot').setAttribute('aria-pressed',String(!showChanges));document.getElementById('changes').setAttribute('aria-pressed',String(showChanges));for(const [i,button] of [...document.getElementById('step-buttons').children].entries())button.setAttribute('aria-pressed',String(i===currentStep));}
for(const [i,step] of steps.entries()){const button=document.createElement('button');button.textContent=step.title;button.addEventListener('click',()=>{currentStep=i;renderStep();});document.getElementById('step-buttons').append(button);}
document.getElementById('previous').addEventListener('click',()=>{if(currentStep>0)currentStep--;renderStep();});document.getElementById('next').addEventListener('click',()=>{if(currentStep<steps.length-1)currentStep++;renderStep();});document.getElementById('snapshot').addEventListener('click',()=>{showChanges=false;renderStep();});document.getElementById('changes').addEventListener('click',()=>{showChanges=true;renderStep();});
function options(id,values){const element=document.getElementById(id);for(const value of values){const option=document.createElement('option');option.value=value;option.textContent=value;element.append(option);}}
options('scenario',[...new Set(records.map(r=>r.scenario))]);options('feature',['All features',...[...new Set(records.map(r=>r.feature))].sort()]);
function renderProbes(){const scenario=document.getElementById('scenario').value;const feature=document.getElementById('feature').value;const filtered=records.filter(r=>r.scenario===scenario&&(feature==='All features'||r.feature===feature));document.getElementById('probe-count').textContent=`${filtered.length} captured query results`;document.getElementById('probe-result').textContent=JSON.stringify(filtered,null,2);}
for(const id of ['scenario','feature'])document.getElementById(id).addEventListener('change',renderProbes);renderStep();renderProbes();
